def upgrade_open_reservations(apps, schema_editor):
    """Reservations made before the approval flow count as accepted: give them a code and a fresh 15 minutes."""
    import secrets
    from datetime import timedelta

    from django.utils import timezone

    Reservation = apps.get_model("seats", "Reservation")
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    now = timezone.now()
    for r in Reservation.objects.filter(status="reserved", confirmation_code__isnull=True).exclude(role="admin"):
        code = "LIB-" + "".join(secrets.choice(alphabet) for _ in range(6))
        r.confirmation_code = code
        r.accepted_at = r.accepted_at or r.created_at
        r.grace_period_expires_at = now + timedelta(minutes=15)
        r.save(update_fields=["confirmation_code", "accepted_at", "grace_period_expires_at"])
    # sessions that were already checked in
    Reservation.objects.filter(status="active", accepted_at__isnull=True).update(accepted_at=models.F("created_at"))


